package com.carebridge.backend.partner.service;import com.carebridge.backend.audit.entity.AuditAction;import com.carebridge.backend.audit.service.AuditService;import com.carebridge.backend.partner.dto.request.ContentDecisionRequest;import com.carebridge.backend.partner.dto.response.ContentDecisionResponse;import com.carebridge.backend.partner.entity.*;import com.carebridge.backend.partner.exception.PartnerException;import com.carebridge.backend.partner.repository.*;import java.time.Instant;import java.util.UUID;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @RequiredArgsConstructor public class SponsoredApprovalServiceImpl implements SponsoredApprovalService{private final PartnerServiceRepository serviceRepo;private final SponsoredCampaignRepository campaignRepo;private final AuditService audit;@Override @Transactional public ContentDecisionResponse decide(PartnerContentTargetType type,UUID id,ContentDecisionRequest request,UUID adminId){if(request.decision()==ContentDecision.REJECT&&(request.reason()==null||request.reason().isBlank()))throw PartnerException.contentDecisionReasonRequired();String previous="PENDING",next=request.decision()==ContentDecision.APPROVE?"APPROVED":"REJECTED";if(type==PartnerContentTargetType.SERVICE){PartnerService target=serviceRepo.findById(id).orElseThrow(PartnerException::contentTargetNotFound);if(target.getApprovalStatus()!=ServiceApprovalStatus.PENDING)throw PartnerException.contentAlreadyDecided();target.setApprovalStatus(ServiceApprovalStatus.valueOf(next));serviceRepo.save(target);}else if(type==PartnerContentTargetType.CAMPAIGN){SponsoredCampaign target=campaignRepo.findById(id).orElseThrow(PartnerException::contentTargetNotFound);if(target.getApprovalStatus()!=CampaignApprovalStatus.PENDING)throw PartnerException.contentAlreadyDecided();target.setApprovalStatus(CampaignApprovalStatus.valueOf(next));target.setReviewedBy(adminId);campaignRepo.save(target);}else throw PartnerException.unsupportedTargetType();audit.log(AuditAction.PARTNER_CONTENT_DECISION,adminId,type.name(),id.toString(),"decision="+request.decision()+",reason="+request.reason());return new ContentDecisionResponse(type,id,previous,next,adminId,request.reason(),Instant.now());}}
